module TlulErrorResponder(
  input        clock,
               reset,
               io_tl_h_a_valid,
  input  [3:0] io_tl_h_a_bits_size,
  input  [7:0] io_tl_h_a_bits_source,
  output       io_tl_h_d_valid,
  output [3:0] io_tl_h_d_bits_size,
  output [7:0] io_tl_h_d_bits_source,
  output       io_tl_h_d_bits_error
);

  reg       d_valid;
  reg [3:0] d_bits_size;
  reg [7:0] d_bits_source;
  reg       d_bits_error;
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      d_valid <= 1'h0;
      d_bits_size <= 4'h0;
      d_bits_source <= 8'h0;
      d_bits_error <= 1'h0;
    end
    else begin
      d_valid <= io_tl_h_a_valid;
      if (io_tl_h_a_valid) begin
        d_bits_size <= io_tl_h_a_bits_size;
        d_bits_source <= io_tl_h_a_bits_source;
      end
      d_bits_error <= 1'h1;
    end
  end // always @(posedge, posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    logic [31:0] _RANDOM[0:5];
    initial begin
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        for (logic [2:0] i = 3'h0; i < 3'h6; i += 3'h1) begin
          _RANDOM[i] = `RANDOM;
        end
        d_valid = _RANDOM[3'h0][0];
        d_bits_size = _RANDOM[3'h0][10:7];
        d_bits_source = _RANDOM[3'h0][18:11];
        d_bits_error = _RANDOM[3'h5][2];
      `endif // RANDOMIZE_REG_INIT
      if (reset) begin
        d_valid = 1'h0;
        d_bits_size = 4'h0;
        d_bits_source = 8'h0;
        d_bits_error = 1'h0;
      end
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  assign io_tl_h_d_valid = d_valid;
  assign io_tl_h_d_bits_size = d_bits_size;
  assign io_tl_h_d_bits_source = d_bits_source;
  assign io_tl_h_d_bits_error = d_bits_error;
endmodule

