  input  [31:0]  io_enq_bits_a_address,
  input  [15:0]  io_enq_bits_a_mask,
  input  [127:0] io_enq_bits_a_data,
  input  [4:0]   io_enq_bits_a_user_rsvd,
  input  [3:0]   io_enq_bits_a_user_instr_type,
  input  [6:0]   io_enq_bits_a_user_cmd_intg,
                 io_enq_bits_a_user_data_intg,
  input  [2:0]   io_enq_bits_spare,
  input          io_deq_ready,
  output         io_deq_valid,
  output [2:0]   io_deq_bits_a_opcode,
                 io_deq_bits_a_param,
  output [3:0]   io_deq_bits_a_size,
  output [7:0]   io_deq_bits_a_source,
  output [31:0]  io_deq_bits_a_address,
  output [15:0]  io_deq_bits_a_mask,
  output [127:0] io_deq_bits_a_data,
  output [4:0]   io_deq_bits_a_user_rsvd,
  output [3:0]   io_deq_bits_a_user_instr_type,
  output [6:0]   io_deq_bits_a_user_cmd_intg,
                 io_deq_bits_a_user_data_intg,
  output [2:0]   io_deq_bits_spare
);

  reg  [219:0] ram;
  reg          full;
  wire         io_deq_valid_0 = io_enq_valid | full;
  wire         do_enq = ~(~full & io_deq_ready) & ~full & io_enq_valid;
  always @(posedge clock or posedge reset) begin
    if (reset)
      full <= 1'h0;
    else if (~(do_enq == (full & io_deq_ready & io_deq_valid_0)))
      full <= do_enq;
  end // always @(posedge, posedge)
  always @(posedge clock) begin
    if (do_enq)
      ram <=
        {io_enq_bits_a_opcode,
         io_enq_bits_a_param,
         io_enq_bits_a_size,
         io_enq_bits_a_source,
         io_enq_bits_a_address,
         io_enq_bits_a_mask,
         io_enq_bits_a_data,
         io_enq_bits_a_user_rsvd,
         io_enq_bits_a_user_instr_type,
         io_enq_bits_a_user_cmd_intg,
         io_enq_bits_a_user_data_intg,
         io_enq_bits_spare};
  end // always @(posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    logic [31:0] _RANDOM[0:6];
    initial begin
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        for (logic [2:0] i = 3'h0; i < 3'h7; i += 3'h1) begin
          _RANDOM[i] = `RANDOM;
        end
        full = _RANDOM[3'h0][0];
        ram =
          {_RANDOM[3'h0][31:1],
           _RANDOM[3'h1],
           _RANDOM[3'h2],
           _RANDOM[3'h3],
           _RANDOM[3'h4],
           _RANDOM[3'h5],
           _RANDOM[3'h6][28:0]};
      `endif // RANDOMIZE_REG_INIT
      if (reset)
        full = 1'h0;
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  assign io_enq_ready = ~full;
  assign io_deq_valid = io_deq_valid_0;
  assign io_deq_bits_a_opcode = full ? ram[219:217] : io_enq_bits_a_opcode;
  assign io_deq_bits_a_param = full ? ram[216:214] : io_enq_bits_a_param;
  assign io_deq_bits_a_size = full ? ram[213:210] : io_enq_bits_a_size;
  assign io_deq_bits_a_source = full ? ram[209:202] : io_enq_bits_a_source;
  assign io_deq_bits_a_address = full ? ram[201:170] : io_enq_bits_a_address;
  assign io_deq_bits_a_mask = full ? ram[169:154] : io_enq_bits_a_mask;
  assign io_deq_bits_a_data = full ? ram[153:26] : io_enq_bits_a_data;
  assign io_deq_bits_a_user_rsvd = full ? ram[25:21] : io_enq_bits_a_user_rsvd;
  assign io_deq_bits_a_user_instr_type =
    full ? ram[20:17] : io_enq_bits_a_user_instr_type;
  assign io_deq_bits_a_user_cmd_intg = full ? ram[16:10] : io_enq_bits_a_user_cmd_intg;
  assign io_deq_bits_a_user_data_intg = full ? ram[9:3] : io_enq_bits_a_user_data_intg;
  assign io_deq_bits_spare = full ? ram[2:0] : io_enq_bits_spare;
endmodule

