  assign io_in_2_ready = ~_grant_T;
  assign io_in_3_ready = ~_grant_T_1;
  assign io_in_4_ready = ~_io_out_valid_T;
  assign io_out_valid = _io_out_valid_T | io_in_4_valid;
  assign io_out_bits_addr =
    io_in_0_valid
      ? io_in_0_bits_addr
      : io_in_1_valid
          ? io_in_1_bits_addr
          : io_in_2_valid
              ? io_in_2_bits_addr
              : io_in_3_valid ? io_in_3_bits_addr : io_in_4_bits_addr;
  assign io_out_bits_data =
    io_in_0_valid
      ? io_in_0_bits_data
      : io_in_1_valid
