module CoralNPURRArbiter_3(
  input          clock,
                 reset,
  output         io_in_0_ready,
  input          io_in_0_valid,
  input  [3:0]   io_in_0_bits_size,
  input  [5:0]   io_in_0_bits_source,
  input  [31:0]  io_in_0_bits_address,
  input  [3:0]   io_in_0_bits_user_instr_type,
  output         io_in_1_ready,
  input          io_in_1_valid,
  input  [2:0]   io_in_1_bits_opcode,
  input  [3:0]   io_in_1_bits_size,
  input  [5:0]   io_in_1_bits_source,
  input  [31:0]  io_in_1_bits_address,
  input  [15:0]  io_in_1_bits_mask,
  input  [127:0] io_in_1_bits_data,
  input  [3:0]   io_in_1_bits_user_instr_type,
  input          io_out_ready,
  output         io_out_valid,
  output [2:0]   io_out_bits_opcode,
  output [3:0]   io_out_bits_size,
  output [5:0]   io_out_bits_source,
  output [31:0]  io_out_bits_address,
  output [15:0]  io_out_bits_mask,
  output [127:0] io_out_bits_data,
  output [3:0]   io_out_bits_user_instr_type
);

  wire io_chosen_choice;
  wire io_out_valid_0 = io_chosen_choice ? io_in_1_valid : io_in_0_valid;
  reg  ctrl_validMask_grantMask_lastGrant;
  wire ctrl_validMask_1 = io_in_1_valid & ~ctrl_validMask_grantMask_lastGrant;
  assign io_chosen_choice = ctrl_validMask_1 | ~io_in_0_valid;
  always @(posedge clock or posedge reset) begin
    if (reset)
      ctrl_validMask_grantMask_lastGrant <= 1'h0;
    else if (io_out_ready & io_out_valid_0)
      ctrl_validMask_grantMask_lastGrant <= io_chosen_choice;
  end // always @(posedge, posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    logic [31:0] _RANDOM[0:0];
    initial begin
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        _RANDOM[/*Zero width*/ 1'b0] = `RANDOM;
        ctrl_validMask_grantMask_lastGrant = _RANDOM[/*Zero width*/ 1'b0][0];
      `endif // RANDOMIZE_REG_INIT
      if (reset)
        ctrl_validMask_grantMask_lastGrant = 1'h0;
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  assign io_in_0_ready = ~ctrl_validMask_1 & io_out_ready;
  assign io_in_1_ready =
    (~ctrl_validMask_grantMask_lastGrant | ~(ctrl_validMask_1 | io_in_0_valid))
    & io_out_ready;
  assign io_out_valid = io_out_valid_0;
  assign io_out_bits_opcode = io_chosen_choice ? io_in_1_bits_opcode : 3'h4;
  assign io_out_bits_size = io_chosen_choice ? io_in_1_bits_size : io_in_0_bits_size;
  assign io_out_bits_source =
    io_chosen_choice ? io_in_1_bits_source : io_in_0_bits_source;
  assign io_out_bits_address =
    io_chosen_choice ? io_in_1_bits_address : io_in_0_bits_address;
  assign io_out_bits_mask = io_chosen_choice ? io_in_1_bits_mask : 16'hFFFF;
  assign io_out_bits_data = io_chosen_choice ? io_in_1_bits_data : 128'h0;
  assign io_out_bits_user_instr_type =
    io_chosen_choice ? io_in_1_bits_user_instr_type : io_in_0_bits_user_instr_type;
