module AsyncQueueSource_UInt8(
  input        clock,
               reset,
  output       io_enq_ready,
  input        io_enq_valid,
  input  [7:0] io_enq_bits,
  output [7:0] io_async_mem_0,
               io_async_mem_1,
  input  [1:0] io_async_ridx,
  output [1:0] io_async_widx
);

  reg        ready_reg;
  wire [1:0] _ridx_ridx_gray_io_q;
  reg  [7:0] mem_0;
  reg  [7:0] mem_1;
  wire       _widx_T_1 = ready_reg & io_enq_valid;
  reg  [1:0] widx_widx_bin;
  reg  [1:0] widx_gray;
  always @(posedge clock) begin
    if (_widx_T_1 & ~(^widx_gray))
      mem_0 <= io_enq_bits;
    if (_widx_T_1 & ^widx_gray)
      mem_1 <= io_enq_bits;
  end // always @(posedge)
  wire [1:0] _widx_incremented_T = widx_widx_bin + {1'h0, _widx_T_1};
  wire [1:0] widx = {_widx_incremented_T[1], ^_widx_incremented_T};
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      widx_widx_bin <= 2'h0;
      ready_reg <= 1'h0;
      widx_gray <= 2'h0;
    end
