module SpiMasterCtrl(
  input         clock,
                reset,
  output        io_tl_a_ready,
  input         io_tl_a_valid,
  input  [2:0]  io_tl_a_bits_opcode,
  input  [1:0]  io_tl_a_bits_size,
  input  [9:0]  io_tl_a_bits_source,
  input  [31:0] io_tl_a_bits_address,
                io_tl_a_bits_data,
  input         io_tl_d_ready,
  output        io_tl_d_valid,
  output [2:0]  io_tl_d_bits_opcode,
  output [1:0]  io_tl_d_bits_size,
  output [9:0]  io_tl_d_bits_source,
  output [31:0] io_tl_d_bits_data,
  output [6:0]  io_tl_d_bits_user_rsp_intg,
                io_tl_d_bits_user_data_intg,
  output        io_tl_d_bits_error,
                io_spi_sclk,
                io_spi_csb,
                io_spi_mosi,
  input         io_spi_miso
);

  wire [6:0]      _intg_gen_io_d_o_user_rsp_intg;
  wire [6:0]      _intg_gen_io_d_o_user_data_intg;
  wire            _rx_fifo_io_enq_ready;
  wire            _rx_fifo_io_deq_valid;
  wire [7:0]      _rx_fifo_io_deq_bits;
  wire            _tx_fifo_io_enq_ready;
  wire            _tx_fifo_io_deq_valid;
  wire [7:0]      _tx_fifo_io_deq_bits;
  reg  [31:0]     reg_control;
  reg  [31:0]     reg_csid;
  reg  [31:0]     reg_csmode;
  reg  [1:0]      state;
  reg  [2:0]      bit_count;
  reg  [7:0]      clk_count;
  reg  [7:0]      shift_reg;
  reg             sclk_reg;
  reg             csb_reg;
  wire            _GEN = clk_count == reg_control[15:8];
  wire            tick = reg_control[0] & _GEN;
  reg             phase;
  wire            _GEN_0 = state == 2'h0;
  wire            _GEN_1 = state == 2'h1;
  wire            _GEN_2 = state == 2'h2;
  wire            _GEN_3 = (&state) & tick;
  wire            _GEN_4 = _GEN_1 | _GEN_2;
  wire            _GEN_5 = ~(reg_control[0]) | _GEN_0 | _GEN_4;
  wire            _is_txdata_write_T = io_tl_a_bits_address[11:0] == 12'h8;
  wire            _is_write_T = io_tl_a_bits_opcode == 3'h0;
  wire            _is_write_T_1 = io_tl_a_bits_opcode == 3'h1;
  wire            _is_rxdata_read_T = io_tl_a_bits_address[11:0] == 12'hC;
  reg             tl_d_valid;
  reg  [2:0]      tl_d_opcode;
  reg  [31:0]     tl_d_data;
  reg  [1:0]      tl_d_size;
  reg  [31:0]     tl_d_source;
  reg             tl_d_error;
  wire            io_tl_a_ready_0 =
    ~tl_d_valid
    & (io_tl_a_valid & _is_txdata_write_T & (_is_write_T | _is_write_T_1)
         ? _tx_fifo_io_enq_ready
         : ~(io_tl_a_valid & _is_rxdata_read_T & io_tl_a_bits_opcode == 3'h4)
           | _rx_fifo_io_deq_valid);
  wire            _GEN_6 = io_tl_a_ready_0 & io_tl_a_valid;
  wire            is_write = _is_write_T | _is_write_T_1;
  wire            _GEN_7 = io_tl_a_bits_address[11:0] == 12'h4;
  wire            _GEN_8 = io_tl_a_bits_address[11:0] == 12'h10;
  wire            _GEN_9 = _GEN_6 & is_write;
  wire            _GEN_10 = io_tl_a_bits_address[11:0] == 12'h14;
  wire            _GEN_11 = _GEN_7 | _GEN_8 | _GEN_10;
  wire            _GEN_12 = reg_csmode[0] ? ~(reg_csid[0]) : csb_reg;
  wire            _GEN_13 = ~(reg_control[0]) | _GEN_0;
  wire            _GEN_14 = bit_count == 3'h0;
  wire [3:0][1:0] _GEN_15 =
    {{_GEN_3 ? 2'h0 : state},
     {tick & phase & _GEN_14 & _rx_fifo_io_enq_ready ? 2'h3 : state},
     {tick ? 2'h2 : state},
     {_tx_fifo_io_deq_valid ? 2'h1 : state}};
  wire            _GEN_16 = _GEN_2 & tick;
  always @(posedge clock) begin
    if (reset) begin
      reg_control <= 32'h0;
      reg_csid <= 32'h0;
      reg_csmode <= 32'h0;
      state <= 2'h0;
      bit_count <= 3'h0;
      clk_count <= 8'h0;
      sclk_reg <= 1'h0;
      csb_reg <= 1'h1;
      phase <= 1'h0;
      tl_d_valid <= 1'h0;
    end
    else begin
      if (_GEN_6 & is_write & _GEN_7)
        reg_control <= io_tl_a_bits_data;
      if (~_GEN_9 | _GEN_7 | ~_GEN_8) begin
      end
      else
        reg_csid <= io_tl_a_bits_data;
      if (~_GEN_9 | _GEN_7 | _GEN_8 | ~_GEN_10) begin
      end
      else
        reg_csmode <= io_tl_a_bits_data;
      if (reg_control[0]) begin
        state <= _GEN_15[state];
        if (_GEN_0) begin
          if (_tx_fifo_io_deq_valid)
            bit_count <= 3'h7;
        end
        else if (_GEN_1 | ~_GEN_16 | ~phase | _GEN_14) begin
        end
        else
          bit_count <= bit_count - 3'h1;
      end
      else
        state <= 2'h0;
      if (_GEN_13) begin
        clk_count <= 8'h0;
        sclk_reg <= reg_control[1];
      end
      else begin
        if (reg_control[0])
          clk_count <= _GEN ? 8'h0 : clk_count + 8'h1;
        if (_GEN_1) begin
          if (tick)
            sclk_reg <= reg_control[1] ^ ~(reg_control[2]);
        end
        else if (_GEN_16) begin
          if (phase) begin
            if (~_GEN_14)
              sclk_reg <= reg_control[1] ^ ~(reg_control[2]);
          end
          else
            sclk_reg <= reg_control[1] ^ reg_control[2];
        end
      end
      csb_reg <=
        ~(reg_control[0])
        | (_GEN_0
             ? (_tx_fifo_io_deq_valid
                  ? reg_csmode[0] & _GEN_12
                  : ~(reg_csmode[0]) | _GEN_12)
             : ~_GEN_4 & (&state) & tick & ~(reg_csmode[0]) | _GEN_12);
      phase <= ~_GEN_13 & (~_GEN_1 & _GEN_16 ^ phase);
      tl_d_valid <= ~(io_tl_d_ready & tl_d_valid) & (_GEN_6 | tl_d_valid);
    end
    if (_GEN_16 & (phase ^ reg_control[2]))
      shift_reg <= {shift_reg[6:0], io_spi_miso};
    else if (reg_control[0] & _GEN_0 & _tx_fifo_io_deq_valid)
      shift_reg <= _tx_fifo_io_deq_bits;
    if (_GEN_6) begin
      tl_d_opcode <= {2'h0, ~is_write};
      tl_d_size <= io_tl_a_bits_size;
      tl_d_source <= {22'h0, io_tl_a_bits_source};
      tl_d_error <=
        ~(~(|(io_tl_a_bits_address[11:0])) | io_tl_a_bits_address[11:0] == 12'h4
          | io_tl_a_bits_address[11:0] == 12'h8 | io_tl_a_bits_address[11:0] == 12'hC
          | io_tl_a_bits_address[11:0] == 12'h10 | io_tl_a_bits_address[11:0] == 12'h14)
        | (is_write
             ? ~(_GEN_7 | _GEN_8 | _GEN_10 | _is_txdata_write_T)
               & (~(|(io_tl_a_bits_address[11:0])) | _is_rxdata_read_T)
             : ~(~(|(io_tl_a_bits_address[11:0])) | _GEN_7 | _GEN_8 | _GEN_10
                 | _is_rxdata_read_T) & _is_txdata_write_T);
    end
    if (~_GEN_6 | is_write) begin
    end
    else if (|(io_tl_a_bits_address[11:0])) begin
      if (_GEN_7)
        tl_d_data <= reg_control;
      else if (_GEN_8)
        tl_d_data <= reg_csid;
      else if (_GEN_10)
        tl_d_data <= reg_csmode;
      else if (_is_rxdata_read_T)
        tl_d_data <= {24'h0, _rx_fifo_io_deq_bits};
    end
    else
      tl_d_data <= {29'h0, |state, ~_rx_fifo_io_deq_valid, ~_tx_fifo_io_enq_ready};
  end // always @(posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    logic [31:0] _RANDOM[0:5];
    initial begin
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        for (logic [2:0] i = 3'h0; i < 3'h6; i += 3'h1) begin
          _RANDOM[i] = `RANDOM;
        end
        reg_control = _RANDOM[3'h0];
        reg_csid = _RANDOM[3'h1];
        reg_csmode = _RANDOM[3'h2];
        state = _RANDOM[3'h3][1:0];
        bit_count = _RANDOM[3'h3][4:2];
        clk_count = _RANDOM[3'h3][12:5];
        shift_reg = _RANDOM[3'h3][20:13];
        sclk_reg = _RANDOM[3'h3][21];
        csb_reg = _RANDOM[3'h3][22];
        phase = _RANDOM[3'h3][23];
        tl_d_valid = _RANDOM[3'h3][24];
        tl_d_opcode = _RANDOM[3'h3][27:25];
        tl_d_data = {_RANDOM[3'h3][31:28], _RANDOM[3'h4][27:0]};
        tl_d_size = _RANDOM[3'h4][29:28];
        tl_d_source = {_RANDOM[3'h4][31:30], _RANDOM[3'h5][29:0]};
        tl_d_error = _RANDOM[3'h5][30];
      `endif // RANDOMIZE_REG_INIT
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  Queue4_UInt8 tx_fifo (
    .clock        (clock),
    .reset        (reset),
    .io_enq_ready (_tx_fifo_io_enq_ready),
    .io_enq_valid (_GEN_9 & ~_GEN_11 & _is_txdata_write_T),
    .io_enq_bits
      (~_GEN_9 | _GEN_11 | ~_is_txdata_write_T ? 8'h0 : io_tl_a_bits_data[7:0]),
    .io_deq_ready (reg_control[0] & _GEN_0 & _tx_fifo_io_deq_valid),
    .io_deq_valid (_tx_fifo_io_deq_valid),
    .io_deq_bits  (_tx_fifo_io_deq_bits)
  );
  Queue4_UInt8 rx_fifo (
    .clock        (clock),
    .reset        (reset),
    .io_enq_ready (_rx_fifo_io_enq_ready),
    .io_enq_valid (~_GEN_5 & (&state) & tick),
    .io_enq_bits  (_GEN_5 | ~_GEN_3 ? 8'h0 : shift_reg),
    .io_deq_ready
      (_GEN_6 & ~(is_write | ~(|(io_tl_a_bits_address[11:0])) | _GEN_11)
       & _is_rxdata_read_T),
    .io_deq_valid (_rx_fifo_io_deq_valid),
    .io_deq_bits  (_rx_fifo_io_deq_bits)
  );
  ResponseIntegrityGen_4 intg_gen (
    .io_d_i_opcode         (tl_d_opcode),
    .io_d_i_param          (3'h0),
    .io_d_i_size           (tl_d_size),
    .io_d_i_source         (tl_d_source[9:0]),
    .io_d_i_sink           (1'h0),
    .io_d_i_data           (tl_d_data),
    .io_d_i_user_rsp_intg  (_intg_gen_io_d_o_user_rsp_intg),
    .io_d_i_user_data_intg (_intg_gen_io_d_o_user_data_intg),
    .io_d_i_error          (tl_d_error),
    .io_d_o_opcode         (/* unused */),
    .io_d_o_param          (/* unused */),
    .io_d_o_size           (/* unused */),
    .io_d_o_source         (/* unused */),
    .io_d_o_sink           (/* unused */),
    .io_d_o_data           (/* unused */),
    .io_d_o_user_rsp_intg  (_intg_gen_io_d_o_user_rsp_intg),
    .io_d_o_user_data_intg (_intg_gen_io_d_o_user_data_intg),
    .io_d_o_error          (/* unused */)
