module GPIO(
  input         clock,
                reset,
  output        io_tl_a_ready,
  input         io_tl_a_valid,
  input  [2:0]  io_tl_a_bits_opcode,
  input  [1:0]  io_tl_a_bits_size,
  input  [9:0]  io_tl_a_bits_source,
  input  [31:0] io_tl_a_bits_address,
                io_tl_a_bits_data,
  output        io_tl_d_valid,
  output [2:0]  io_tl_d_bits_opcode,
  output [1:0]  io_tl_d_bits_size,
  output [9:0]  io_tl_d_bits_source,
  output [31:0] io_tl_d_bits_data,
  output [6:0]  io_tl_d_bits_user_rsp_intg,
                io_tl_d_bits_user_data_intg,
  output        io_tl_d_bits_error,
  output [7:0]  io_gpio_o,
                io_gpio_en_o,
  input  [7:0]  io_gpio_i
);

  wire [6:0]  _intg_gen_io_d_o_user_rsp_intg;
  wire [6:0]  _intg_gen_io_d_o_user_data_intg;
  reg  [7:0]  data_out;
  reg  [7:0]  out_en;
  reg         tl_d_valid;
  reg  [2:0]  tl_d_opcode;
  reg  [31:0] tl_d_data;
  reg  [1:0]  tl_d_size;
  reg  [31:0] tl_d_source;
  reg         tl_d_error;
  wire        _GEN = ~tl_d_valid & io_tl_a_valid;
  wire        is_write = io_tl_a_bits_opcode == 3'h0 | io_tl_a_bits_opcode == 3'h1;
  wire        _GEN_0 = io_tl_a_bits_address[11:0] == 12'h4;
  wire        _GEN_1 = io_tl_a_bits_address[11:0] == 12'h8;
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      data_out <= 8'h0;
      out_en <= 8'h0;
      tl_d_valid <= 1'h0;
    end
    else begin
      if (_GEN & is_write & _GEN_0)
        data_out <= io_tl_a_bits_data[7:0];
      if (~(_GEN & is_write) | _GEN_0 | ~_GEN_1) begin
      end
      else
        out_en <= io_tl_a_bits_data[7:0];
      tl_d_valid <= ~tl_d_valid & (_GEN | tl_d_valid);
    end
  end // always @(posedge, posedge)
  always @(posedge clock) begin
    if (_GEN) begin
      tl_d_opcode <= {2'h0, ~is_write};
      tl_d_size <= io_tl_a_bits_size;
      tl_d_source <= {22'h0, io_tl_a_bits_source};
      tl_d_error <=
        ~(~(|(io_tl_a_bits_address[11:0])) | io_tl_a_bits_address[11:0] == 12'h4
          | io_tl_a_bits_address[11:0] == 12'h8) | is_write & ~(_GEN_0 | _GEN_1)
        & ~(|(io_tl_a_bits_address[11:0]));
    end
    if (~_GEN | is_write) begin
    end
    else if (|(io_tl_a_bits_address[11:0])) begin
      if (_GEN_0)
        tl_d_data <= {24'h0, data_out};
      else if (_GEN_1)
        tl_d_data <= {24'h0, out_en};
    end
    else
      tl_d_data <= {24'h0, io_gpio_i};
  end // always @(posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    logic [31:0] _RANDOM[0:2];
    initial begin
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        for (logic [1:0] i = 2'h0; i < 2'h3; i += 2'h1) begin
          _RANDOM[i] = `RANDOM;
        end
        data_out = _RANDOM[2'h0][7:0];
        out_en = _RANDOM[2'h0][15:8];
        tl_d_valid = _RANDOM[2'h0][16];
        tl_d_opcode = _RANDOM[2'h0][19:17];
        tl_d_data = {_RANDOM[2'h0][31:20], _RANDOM[2'h1][19:0]};
        tl_d_size = _RANDOM[2'h1][21:20];
        tl_d_source = {_RANDOM[2'h1][31:22], _RANDOM[2'h2][21:0]};
        tl_d_error = _RANDOM[2'h2][22];
      `endif // RANDOMIZE_REG_INIT
      if (reset) begin
        data_out = 8'h0;
        out_en = 8'h0;
        tl_d_valid = 1'h0;
      end
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  ResponseIntegrityGen_4_1 intg_gen (
    .io_d_i_opcode         (tl_d_opcode),
    .io_d_i_param          (3'h0),
    .io_d_i_size           (tl_d_size),
    .io_d_i_source         (tl_d_source[9:0]),
    .io_d_i_sink           (1'h0),
    .io_d_i_data           (tl_d_data),
    .io_d_i_user_rsp_intg  (_intg_gen_io_d_o_user_rsp_intg),
    .io_d_i_user_data_intg (_intg_gen_io_d_o_user_data_intg),
    .io_d_i_error          (tl_d_error),
    .io_d_o_opcode         (/* unused */),
    .io_d_o_param          (/* unused */),
    .io_d_o_size           (/* unused */),
    .io_d_o_source         (/* unused */),
    .io_d_o_sink           (/* unused */),
    .io_d_o_data           (/* unused */),
    .io_d_o_user_rsp_intg  (_intg_gen_io_d_o_user_rsp_intg),
    .io_d_o_user_data_intg (_intg_gen_io_d_o_user_data_intg),
    .io_d_o_error          (/* unused */)
  );
  assign io_tl_a_ready = ~tl_d_valid;
  assign io_tl_d_valid = tl_d_valid;
  assign io_tl_d_bits_opcode = tl_d_opcode;
  assign io_tl_d_bits_size = tl_d_size;
  assign io_tl_d_bits_source = tl_d_source[9:0];
  assign io_tl_d_bits_data = tl_d_data;
  assign io_tl_d_bits_user_rsp_intg = _intg_gen_io_d_o_user_rsp_intg;
  assign io_tl_d_bits_user_data_intg = _intg_gen_io_d_o_user_data_intg;
  assign io_tl_d_bits_error = tl_d_error;
  assign io_gpio_o = data_out;
  assign io_gpio_en_o = out_en;
endmodule

