          .rst_ni,
          .operands_i      ( local_operands               ),
          .is_boxed_i      ( is_boxed_i[NUM_OPERANDS-1:0] ),
          .rnd_mode_i,
          .op_i,
          .op_mod_i,
          .tag_i,
          .mask_i            ( simd_mask_i[lane]     ),
          .aux_i             ( vectorial_op          ), // Remember whether operation was vectorial
          .in_valid_i        ( in_valid              ),
          .in_ready_o        ( lane_in_ready[lane]   ),
          .flush_i,
          .result_o          ( op_result             ),
          .status_o          ( op_status             ),
