assign vdiv_qt_rt[QT_WIDTH-1:0] = srt_remainder[REM_WIDTH-1] 
                                  ? total_qt_rt_minus[QT_WIDTH-1:0]
                                  : total_qt_rt[QT_WIDTH-1:0];

assign qt_rt_const_shift_std_next[QT_WIDTH-1:0] = {4'b0, qt_rt_const_shift_std[QT_WIDTH-1:4]};

