  assign vector_csr_ari = lcmd_valid ? lcmd.cmd.arch_state : 'b0;
  assign csr_vstart     = lcmd_valid ? lcmd.cmd.arch_state.vstart : 'b0;
  assign rs1            = lcmd_valid ? lcmd.cmd.rs1 : 'b0;
  assign uop_vstart     = lcmd_valid ? lcmd.uop_vstart : 'b0;
  assign uop_index_max  = lcmd_valid ? lcmd.uop_index_max : 'b0;
  assign emul_vd        = lcmd_valid ? lcmd.emul_vd : EMUL_NONE; 
  assign emul_vs2       = lcmd_valid ? lcmd.emul_vs2 : EMUL_NONE;
  assign emul_vs1       = lcmd_valid ? lcmd.emul_vs1 : EMUL_NONE;
  assign emul_max       = lcmd_valid ? lcmd.emul_max : EMUL_NONE;
  assign eew_max        = lcmd_valid ? lcmd.eew_max : EEW_NONE;

  always_comb begin
    // initial the data
    valid_opi = 'b0;
    valid_opm = 'b0;
    `ifdef ZVE32F_ON
    valid_opf = 'b0;
    `endif    

    case(inst_funct3)
      OPIVV,
      OPIVX,
      OPIVI: valid_opi = lcmd_valid;
      OPMVV,
      OPMVX: valid_opm = lcmd_valid;
    `ifdef ZVE32F_ON
      OPFVV,
      OPFVF: valid_opf = lcmd_valid;
    `endif    
    endcase
  end 

//
// split instruction to uops
//
  // select uop_vstart and uop_index_remain as the base uop_index
  always_comb begin
    // initial
    uop_index_base = (|uop_index_remain) ? uop_index_remain : uop_vstart;

    case(1'b1)
      valid_opi: begin
        case(inst_funct6)
          VSLIDEUP_RGATHEREI16,
          VRGATHER: begin
            uop_index_base = uop_index_remain;
          end
        endcase
      end

      valid_opm: begin
        case(inst_funct6)
          VSLIDE1UP: begin
            uop_index_base = uop_index_remain;
          end
        endcase
      end

    `ifdef ZVE32F_ON
      valid_opf: begin
        case(inst_funct6)
          VFSLIDE1UP: begin
            uop_index_base = uop_index_remain;
          end
        endcase
      end
    `endif
    endcase
  end

  // calculate the uop_index used in decoding uops 
  generate
    for(j=0;j<`NUM_DE_UOP;j++) begin: GET_UOP_INDEX
      assign uop_index_current[j] = {1'b0, uop_index_base} + j[`UOP_INDEX_WIDTH:0];
    end
  endgenerate

  // generate uop valid
  always_comb begin        
    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_UOP_VALID
      uop_valid[i] = lcmd_valid & ({1'b1, uop_index_base} <= ({1'b1,uop_index_max}-i[`UOP_INDEX_WIDTH:0]));
    end
  end

  // update first_uop valid
  always_comb begin
    // initial 
    first_uop_valid = 'b0;
    
    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_UOP_FIRST
      first_uop_valid[i] = uop_index_current[i][`UOP_INDEX_WIDTH-1:0] == uop_vstart;

      case(1'b1)
        valid_opi: begin
          case(inst_funct6)
            VSLIDEUP_RGATHEREI16,
            VRGATHER: begin
              first_uop_valid[i] = uop_index_current[i][`UOP_INDEX_WIDTH-1:0] == 'b0;
            end
          endcase
        end
        valid_opm: begin
          case(inst_funct6)
            VSLIDE1UP: begin
              first_uop_valid[i] = uop_index_current[i][`UOP_INDEX_WIDTH-1:0] == 'b0;
            end
          endcase
        end
        `ifdef ZVE32F_ON
        valid_opf: begin
          case(inst_funct6)
            VFSLIDE1UP: begin
              first_uop_valid[i] = uop_index_current[i][`UOP_INDEX_WIDTH-1:0] == 'b0;
            end
          endcase
        end
        `endif
      endcase
    end
  end

  // update last_uop valid
  always_comb begin
    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_UOP_LAST
      last_uop_valid[i] = uop_index_current[i][`UOP_INDEX_WIDTH-1:0] == uop_index_max;
    end
  end

  // allocate uop to execution unit
  always_comb begin
    // initial
    uop_exe_unit = ALU;
    
    case(1'b1)
      valid_opi: begin
        // allocate OPI* uop to execution unit
        case(inst_funct6)
          VADD,
          VSUB,
          VRSUB,
          VADC,
          VSBC,
          VAND,
          VOR,
          VXOR,
          VSLL,
          VSRL,
          VSRA,
          VNSRL,
          VNSRA,
          VMINU,
          VMIN,
          VMAXU,
          VMAX,
          VMERGE_VMV,
          VSADDU,
          VSADD,
          VSSUBU,
          VSSUB,
          VSSRL,
          VSSRA,
          VNCLIPU,
          VNCLIP: begin
            uop_exe_unit = ALU;
          end 
          
          VMADC,
          VMSBC,
          VMSEQ,
          VMSNE,
          VMSLTU,
          VMSLT,
          VMSLEU,
          VMSLE,
          VMSGTU,
          VMSGT:begin
            uop_exe_unit = CMP;
          end
          
          VWREDSUMU,
          VWREDSUM: begin
            uop_exe_unit = RDT;
          end

          VSLIDEUP_RGATHEREI16,
          VSLIDEDOWN,
          VRGATHER: begin
            uop_exe_unit = PMT;
          end

          VSMUL_VMVNRR: begin
            uop_exe_unit = (inst_funct3==OPIVI) ? ALU : MUL;
          end
        endcase
      end

      valid_opm: begin
        // allocate OPM* uop to execution unit
        case(inst_funct6)
          VWADDU,
          VWSUBU,
          VWADD,
          VWSUB,
          VWADDU_W,
          VWSUBU_W,
          VWADD_W,
          VWSUB_W,
          VXUNARY0,
          VAADDU,
          VAADD,
          VASUBU,
          VASUB,
          VMAND,
          VMNAND,
          VMANDN,
          VMXOR,
          VMOR,
          VMNOR,
          VMORN,
          VMXNOR: begin
            uop_exe_unit = ALU;
          end

          VMUL,
          VMULH,
          VMULHU,
          VMULHSU,
          VWMUL,
          VWMULU,
          VWMULSU: begin
            uop_exe_unit = MUL;
          end

          VDIVU,
          VDIV,
          VREMU,
          VREM: begin
            uop_exe_unit = DIV;
          end
          
          VMACC,
          VNMSAC,
          VMADD,
          VNMSUB,
          VWMACCU,
          VWMACC,
          VWMACCSU,
          VWMACCUS: begin
            uop_exe_unit = MAC;
          end

          // reduction
          VREDSUM,
          VREDMAXU,
          VREDMAX,
          VREDMINU,
          VREDMIN,
          VREDAND,
          VREDOR,
          VREDXOR: begin
            uop_exe_unit = RDT;
          end

          VWRXUNARY0: begin
            uop_exe_unit = (vs1_opcode==VCPOP)&(inst_funct3==OPMVV) ? MISC : ALU;
          end
          
          VMUNARY0: begin
            uop_exe_unit = (vs1_opcode==VIOTA) ? MISC : ALU;
          end

          VSLIDE1UP,
          VSLIDE1DOWN,
          VCOMPRESS: begin
            uop_exe_unit = PMT;
          end
        endcase
      end

      `ifdef ZVE32F_ON
      valid_opf: begin
        // allocate OPF* uop to execution unit
        case(inst_funct6)
          `ifdef ZVFBFWMA_ON
          VFWMACCBF16,
          `endif
          VFADD,
          VFSUB,      
          VFRSUB,     
          VFMUL,      
          VFMACC,     
          VFNMACC,    
          VFMSAC,     
          VFNMSAC,    
          VFMADD,     
          VFNMADD,    
          VFMSUB,     
          VFNMSUB: begin
            uop_exe_unit = FMA;
          end

          VFDIV,      
          VFRDIV: begin
            uop_exe_unit = FDIV;
          end

          VFUNARY1: begin
            case(vs1_opcode)
              VFSQRT: begin
                uop_exe_unit = FDIV;
              end
              VFRSQRT7,
              VFREC7: begin
                uop_exe_unit = FTBL;
              end
              VFCLASS: begin
                uop_exe_unit = FNCMP;
              end
            endcase
          end

          VFMIN,
          VFMAX,
          VFSGNJ,
          VFSGNJN,
          VFSGNJX: begin
            uop_exe_unit = FNCMP;
          end

          VMFEQ,
          VMFNE,
          VMFLT,
          VMFLE,
          VMFGT,
          VMFGE: begin
            uop_exe_unit = FCMP;
          end

          VFMERGE_VFMV,
          VWRFUNARY0: begin
            uop_exe_unit = ALU;
          end

          VFUNARY0: begin
            case(vs1_opcode)
              `ifdef ZVFBFWMA_ON
              VFNCVTBF16,
              VFWCVTBF16,
              `endif
              VFCVT_XUFV, 
              VFCVT_XFV,
              VFCVT_RTZXUFV,
              VFCVT_RTZXFV,
              VFCVT_FXUV,
              VFCVT_FXV: begin
                uop_exe_unit = FCVT;
              end
            endcase
          end

          VFREDOSUM,
          VFREDUSUM,
          VFREDMAX,
          VFREDMIN: begin
            uop_exe_unit = FRDT;
          end

          VFSLIDE1UP,
          VFSLIDE1DOWN: begin
            uop_exe_unit = PMT;
          end
        endcase
      end
      `endif  
    endcase
  end

  // update uop class
  always_comb begin
    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_UOP_CLASS
      // initial 
      uop_class[i] = XXX;
      
      case(1'b1)
        valid_opi: begin
          // OPI*
          case(inst_funct6)
            VADD,
            VSUB,
            VRSUB,
            VADC,
            VSBC,
            VAND,
            VOR,
            VXOR,
            VSLL,
            VSRL,
            VSRA,
            VNSRL,
            VNSRA,
            VMINU,
            VMIN,
            VMAXU,
            VMAX,
            VSADDU,
            VSADD,
            VSSUBU,
            VSSUB,
            VSMUL_VMVNRR,
            VSSRL,
            VSSRA,
            VNCLIPU,
            VNCLIP: begin
              if(inst_funct3==OPIVV)
                uop_class[i] = XVV;
              else
                uop_class[i] = XVX;
            end

            VWREDSUMU,
            VWREDSUM: begin
              if(first_uop_valid[i])
                uop_class[i] = XVV;
              else
                uop_class[i] = XVX;
            end

            VMADC,
            VMSBC,
            VMSEQ,
            VMSNE,
            VMSLTU,
            VMSLT,
            VMSLEU,
            VMSLE,
            VMSGTU,
            VMSGT: begin
              if(last_uop_valid[i])
                uop_class[i] = inst_funct3==OPIVV ? VVV : VVX;
              else
                uop_class[i] = inst_funct3==OPIVV ? XVV : XVX;
            end

            VMERGE_VMV: begin
              if(inst_funct3==OPIVV)
                uop_class[i] = inst_vm ? XXV : XVV;
              else
                uop_class[i] = inst_vm ? XXX : XVX;
            end

            VSLIDEUP_RGATHEREI16,
            VSLIDEDOWN,
            VRGATHER: begin
              if(inst_funct3==OPIVV)
                uop_class[i] = XXV;
              else   
                uop_class[i] = XXX;
            end
          endcase
        end

        valid_opm: begin
          // OPM*
          case(inst_funct6)
            VWADDU,
            VWSUBU,
            VWADD,
            VWSUB,
            VWADDU_W,
            VWSUBU_W,
            VWADD_W,
            VWSUB_W,
            VMUL,
            VMULH,
            VMULHU,
            VMULHSU,
            VDIVU,
            VDIV,
            VREMU,
            VREM,
            VWMUL,
            VWMULU,
            VWMULSU,
            VAADDU,
            VAADD,
            VASUBU,
            VASUB: begin
              if(inst_funct3==OPMVV)
                uop_class[i] = XVV;
              else
                uop_class[i] = XVX;
            end

            // reduction
            VREDSUM,
            VREDMAXU,
            VREDMAX,
            VREDMINU,
            VREDMIN,
            VREDAND,
            VREDOR,
            VREDXOR: begin
              if(first_uop_valid[i])
                uop_class[i] = XVV;
              else
                uop_class[i] = XVX;
            end

            VSLIDE1UP,
            VSLIDE1DOWN: begin
                uop_class[i] = XXX;
            end 
            
            VXUNARY0: begin
              uop_class[i]  = XVX;
            end

            VMACC,
            VNMSAC,
            VMADD,
            VNMSUB,
            VWMACCU,
            VWMACC,
            VWMACCSU,
            VWMACCUS: begin
              if(inst_funct3==OPMVV)
                uop_class[i] = VVV;
              else
                uop_class[i] = VVX;
            end

            // permutation
            VCOMPRESS: begin
              if(first_uop_valid[i]) 
                uop_class[i] = XXV;
              else
                uop_class[i] = XXX;
            end

            // mask
            VMAND,
            VMNAND,
            VMANDN,
            VMXOR,
            VMOR,
            VMNOR,
            VMORN,
            VMXNOR: begin
              uop_class[i] = (csr_vstart=='b0) ? XVV : VVV;
            end

            VWRXUNARY0: begin
              if(inst_funct3==OPMVV)
                uop_class[i] = XVX;
              else
                uop_class[i] = XXX;
            end

            VMUNARY0: begin
              case(vs1_opcode)
                VMSBF,
                VMSIF,
                VMSOF: begin
                  uop_class[i] = inst_vm ? XVX: VVX;
                end
                VIOTA: begin
                  uop_class[i] = first_uop_valid[i] ? XVX : XXX;
                end
                VID: begin
                  uop_class[i] = XXX;
                end
              endcase
            end
          endcase
        end

        `ifdef ZVE32F_ON
        valid_opf: begin
          // OPF* instruction
          case(inst_funct6)
            VFADD,          
            VFSUB,      
            VFRSUB,
            VFMUL,      
            VFDIV,      
            VFRDIV,     
            VFMIN,
            VFMAX,
            VFSGNJ,
            VFSGNJN,
            VFSGNJX,
            VFSLIDE1UP,
            VFSLIDE1DOWN: begin
              if(inst_funct3==OPFVV)
                uop_class[i] = XVV;
              else
                uop_class[i] = XVX;
            end 

            `ifdef ZVFBFWMA_ON
            VFWMACCBF16,
            `endif
            VFMACC,     
            VFNMACC,    
            VFMSAC,     
            VFNMSAC,    
            VFMADD,     
            VFNMADD,    
            VFMSUB,     
            VFNMSUB:begin
              if(inst_funct3==OPFVV)
                uop_class[i] = VVV;
              else
                uop_class[i] = VVX;
            end

            VFREDOSUM,
            VFREDUSUM,
            VFREDMAX,
            VFREDMIN: begin
              if(first_uop_valid[i])
                uop_class[i] = XVV;
              else
                uop_class[i] = XVX;
            end

            VFUNARY0,
            VFUNARY1: begin
              uop_class[i] = XVX;
            end

            VMFEQ,
            VMFNE,
            VMFLT,
            VMFLE,
            VMFGT,
            VMFGE: begin
              if(last_uop_valid[i]) 
                uop_class[i] = inst_funct3==OPFVV ? VVV : VVX;
              else
                uop_class[i] = inst_funct3==OPFVV ? XVV : XVX;
            end

            VFMERGE_VFMV: begin
              if(inst_vm)
                uop_class[i] = XXX;
              else
                uop_class[i] = XVX;
            end

            VWRFUNARY0: begin
              if(inst_funct3==OPFVV)
                uop_class[i] = XVX;
              else
                uop_class[i] = XXX;
            end
          endcase
        end
        `endif
      endcase
    end
  end

  // update vector_csr and vstart
  always_comb begin
    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_UOP_VCSR
      vector_csr[i] = vector_csr_ari;

      // update vstart of every uop
      if(uop_index_current[i]>{1'b0,uop_vstart}) begin
        case(1'b1)
          valid_opi: begin
            // OPI*
            case(inst_funct6)
              VMADC,
              VMSBC,
              VMSEQ,
              VMSNE,
              VMSLTU,
              VMSLT,
              VMSLEU,
              VMSLE,
              VMSGTU,
              VMSGT,
              VWREDSUMU,
              VWREDSUM: begin
                vector_csr[i].vstart = vector_csr_ari.vstart;
              end
              default: begin 
                case(eew_max)
                  EEW8: begin
                    vector_csr[i].vstart  = {uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0],{($clog2(`VLENB)){1'b0}}};
                  end
                  EEW16: begin
                    vector_csr[i].vstart  = {1'b0,uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0],{($clog2(`VLEN/`HWORD_WIDTH)){1'b0}}};
                  end
                  EEW32: begin
                    vector_csr[i].vstart  = {2'b0,uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0],{($clog2(`VLEN/`WORD_WIDTH)){1'b0}}};
                  end
                endcase
              end
            endcase
          end
          valid_opm: begin
            // OPM*
            case(inst_funct6)
              VREDSUM,
              VREDMAXU,
              VREDMAX,
              VREDMINU,
              VREDMIN,
              VREDAND,
              VREDOR,
              VREDXOR,
              VCOMPRESS: begin
                vector_csr[i].vstart = vector_csr_ari.vstart;
              end
              default: begin 
                case(eew_max)
                  EEW8: begin
                    vector_csr[i].vstart  = {uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0],{($clog2(`VLENB)){1'b0}}};
                  end
                  EEW16: begin
                    vector_csr[i].vstart  = {1'b0,uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0],{($clog2(`VLEN/`HWORD_WIDTH)){1'b0}}};
                  end
                  EEW32: begin
                    vector_csr[i].vstart  = {2'b0,uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0],{($clog2(`VLEN/`WORD_WIDTH)){1'b0}}};
                  end
                endcase
              end
            endcase
          end

          `ifdef ZVE32F_ON
          valid_opf: begin
            // OPF* instruction
            case(inst_funct6)
              VMFEQ,
              VMFNE,
              VMFLT,
              VMFLE,
              VMFGT,
              VMFGE,
              VFREDOSUM,
              VFREDUSUM,
              VFREDMAX,
              VFREDMIN: begin
                vector_csr[i].vstart = vector_csr_ari.vstart;
              end
              default: begin 
                case(eew_max)
                  EEW8: begin
                    vector_csr[i].vstart  = {uop_index_current[i][`UOP_INDEX_WIDTH-1:0],{($clog2(`VLENB)){1'b0}}};
                  end
                  EEW16: begin
                    vector_csr[i].vstart  = {1'b0,uop_index_current[i][`UOP_INDEX_WIDTH-1:0],{($clog2(`VLEN/`HWORD_WIDTH)){1'b0}}};
                  end
                  EEW32: begin
                    vector_csr[i].vstart  = {2'b0,uop_index_current[i][`UOP_INDEX_WIDTH-1:0],{($clog2(`VLEN/`WORD_WIDTH)){1'b0}}};
                  end
                endcase
              end
            endcase
          end
          `endif
        endcase
      end
    end
  end

  // update ignore_vma and ignore_vta
  // some instructions use vm as an extra opcode, so it needs ignore vma policy.
  // the instructions whose EEW_vd=1b can write the result to TAIL elements, so it needs ignore vta policy.
  always_comb begin
    // initial 
    ignore_vma = 'b0;
    ignore_vta = 'b0;
      
    case(inst_funct3) 
      OPIVV,
      OPIVX,
      OPIVI: begin
        case(inst_funct6)
          VADC,
          VSBC: begin
            ignore_vma = 1'b1;
            ignore_vta = 1'b0;
          end
          VMADC,
          VMSBC,
          VMSEQ,
          VMSNE,
          VMSLTU,
          VMSLT,
          VMSLEU,
          VMSLE,
          VMSGTU,
          VMSGT: begin
            ignore_vma = 1'b1;
            ignore_vta = 1'b1;
          end
          VMERGE_VMV: begin
            if (inst_vm=='b0) begin
              ignore_vma = 1'b1;
            end
          end
        endcase
      end

      OPMVV: begin
        case(inst_funct6)
          VMANDN,
          VMAND,
          VMOR,
          VMXOR,
          VMORN,
          VMNAND,
          VMNOR,
          VMXNOR: begin
            ignore_vma = 1'b1;
            ignore_vta = 1'b1;
          end
          VMUNARY0: begin
            case(vs1_opcode)
              VMSBF,
              VMSOF,
              VMSIF: begin
                ignore_vma = 1'b1;
                ignore_vta = 1'b1;
              end
            endcase
          end
        endcase
      end

    `ifdef ZVE32F_ON
    OPFVV: begin
      case(inst_funct6)
        VMFEQ,
        VMFNE,
        VMFLT,
        VMFLE: begin
          ignore_vma = 1'b1;
          ignore_vta = 1'b1;
        end
        VWRFUNARY0: begin
          ignore_vma = 1'b1;
          ignore_vta = 1'b0;
        end
      endcase
    end
    OPFVF: begin
      case(inst_funct6)
        VMFEQ,
        VMFNE,
        VMFLT,
        VMFLE,
        VMFGT,
        VMFGE: begin
          ignore_vma = 1'b1;
          ignore_vta = 1'b1;
        end
        VFMERGE_VFMV,
        VWRFUNARY0: begin
          ignore_vma = 1'b1;
          ignore_vta = 1'b0;
        end
      endcase
    end
    `endif
    endcase
  end
  
  // some uop need v0 as the vector operand
  always_comb begin
    // initial 
    v0_valid = 'b0;
       
    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_UOP_V0
      case(1'b1)
        valid_opi: begin
          // OPI*
          case(inst_funct6)
            VADC,
            VMADC,
            VSBC,
            VMSBC,
            VMERGE_VMV: begin
              v0_valid[i] = !inst_vm;
            end

            VMSEQ,
            VMSNE,
            VMSLTU,
            VMSLT,
            VMSLEU,
            VMSLE,
            VMSGTU,
            VMSGT: begin
              v0_valid[i] = inst_vm ? 'b0 : last_uop_valid[i]; 
            end
          endcase
        end
        valid_opm: begin
          // OPM*
          case(inst_funct6)
            VWRXUNARY0: begin
              case(vs1_opcode)
                VCPOP,
                VFIRST: begin
                  v0_valid[i] = !inst_vm;
                end
              endcase
            end
            VMUNARY0: begin
              case(vs1_opcode)
                VMSBF,
                VMSOF,
                VMSIF,
                VIOTA: begin
                  v0_valid[i] = !inst_vm;
                end
              endcase
            end
          endcase
        end
        `ifdef ZVE32F_ON
        valid_opf: begin
          // OPF* instruction
          case(inst_funct6)
            VMFEQ,
            VMFNE,
            VMFLT,
            VMFLE,
            VMFGT,
            VMFGE: begin
              v0_valid[i] = inst_vm ? 'b0 : last_uop_valid[i]; 
            end
            VFMERGE_VFMV: begin
              v0_valid[i] = !inst_vm;
            end
          endcase
        end
        `endif        
      endcase
    end
  end    
  
  // update vd_offset and valid
  always_comb begin
    vd_offset = 'b0;
    vd_valid  = 'b0;

    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_VD_OFFSET  
      case(1'b1)
        valid_opi: begin
          case(inst_funct6)
            VADD,
            VSUB,
            VRSUB,
            VADC,
            VSBC,
            VAND,
            VOR,
            VXOR,
            VSLL,
            VSRL,
            VSRA,
            VMINU,
            VMIN,
            VMAXU,
            VMAX,
            VMERGE_VMV,
            VSADDU,
            VSADD,
            VSSUBU,
            VSSUB,
            VSMUL_VMVNRR,
            VSSRL,
            VSSRA,
            VSLIDEDOWN,
            VRGATHER: begin
              vd_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
              vd_valid[i]  = 1'b1;
            end

            VMADC,
            VMSBC,
            VMSEQ,
            VMSNE,
            VMSLTU,
            VMSLT,
            VMSLEU,
            VMSLE,
            VMSGTU,
            VMSGT,
            VWREDSUMU,
            VWREDSUM: begin
              vd_offset[i] = 'b0;
              vd_valid[i]  = last_uop_valid[i];
            end

            VNSRL,
            VNSRA,
            VNCLIPU,
            VNCLIP: begin
              vd_offset[i] = {1'b0, uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:1]};
              vd_valid[i]  = 1'b1;
            end

            VSLIDEUP_RGATHEREI16: begin
              case(inst_funct3)
                OPIVV: begin
                  case({emul_max,emul_vd})
                    {EMUL1,EMUL1},
                    {EMUL2,EMUL2},
                    {EMUL4,EMUL4},
                    {EMUL8,EMUL8}: begin
                      vd_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
                      vd_valid[i]  = 1'b1;
                    end
                    {EMUL2,EMUL1},
                    {EMUL4,EMUL2},
                    {EMUL8,EMUL4}: begin
                      vd_offset[i] = {1'b0, uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:1]};
                      vd_valid[i]  = 1'b1;                    
                    end
                  endcase
                end
                OPIVX,
                OPIVI: begin  
                  vd_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
                  vd_valid[i]  = 1'b1;
                end 
              endcase
            end
          endcase
        end

        valid_opm: begin
          // OPM*
          case(inst_funct6)
            VWADDU,
            VWSUBU,
            VWADD,
            VWSUB,
            VWADDU_W,
            VWSUBU_W,
            VWADD_W,
            VWSUB_W,
            VXUNARY0,
            VMUL,
            VMULH,
            VMULHU,
            VMULHSU,
            VDIVU,
            VDIV,
            VREMU,
            VREM,
            VWMUL,
            VWMULU,
            VWMULSU,
            VWMACCUS,
            VMACC,
            VNMSAC,
            VMADD,
            VNMSUB,
            VWMACCU,
            VWMACC,
            VWMACCSU,
            VAADDU,
            VAADD,
            VASUBU,
            VASUB,
            VSLIDE1UP,
            VSLIDE1DOWN,
            VCOMPRESS: begin
              vd_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
              vd_valid[i]  = 1'b1;
            end   

            VREDSUM,
            VREDMAXU,
            VREDMAX,
            VREDMINU,
            VREDMIN,
            VREDAND,
            VREDOR,
            VREDXOR: begin
              vd_offset[i] = 'b0;
              vd_valid[i]  = last_uop_valid[i];
            end
             
            VMAND,
            VMNAND,
            VMANDN,
            VMXOR,
            VMOR,
            VMNOR,
            VMORN,
            VMXNOR: begin
              vd_offset[i] = 'b0;
              vd_valid[i]  = 1'b1;
            end

            VWRXUNARY0: begin
              case(inst_funct3)
                OPMVX: begin
                  vd_offset[i] = 'b0;
                  vd_valid[i]  = 1'b1;
                end
              endcase
            end
         
            VMUNARY0: begin
              case(vs1_opcode)
                VMSBF,
                VMSIF,
                VMSOF: begin
                  vd_offset[i] = 'b0;
                  vd_valid[i]  = 1'b1;
                end
                VIOTA,
                VID: begin
                  vd_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
                  vd_valid[i]  = 1'b1;
                end
              endcase
            end
          endcase
        end

        `ifdef ZVE32F_ON
        valid_opf: begin
          // OPF* instruction
          case(inst_funct6)
            `ifdef ZVFBFWMA_ON
            VFWMACCBF16,
            `endif
            VFADD,  
            VFSUB,      
            VFRSUB,     
            VFMUL,      
            VFDIV,      
            VFRDIV,     
            VFMACC,     
            VFNMACC,    
            VFMSAC,     
            VFNMSAC,    
            VFMADD,     
            VFNMADD,    
            VFMSUB,     
            VFNMSUB,    
            VFUNARY1,
            VFMIN,
            VFMAX,
            VFSGNJ,
            VFSGNJN,
            VFSGNJX,
            VFMERGE_VFMV,
            VFSLIDE1UP,
            VFSLIDE1DOWN: begin
              vd_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
              vd_valid[i]  = 1'b1;
            end

            VMFEQ,
            VMFNE,
            VMFLT,
            VMFLE,
            VMFGT,
            VMFGE,
            VFREDOSUM,
            VFREDUSUM,
            VFREDMAX,
            VFREDMIN: begin
              vd_offset[i] = 'b0;
              vd_valid[i]  = last_uop_valid[i];
            end

            VFUNARY0: begin
              case(vs1_opcode)
                `ifdef ZVFBFWMA_ON
                VFNCVTBF16: begin
                  vd_offset[i] = {1'b0, uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:1]};
                  vd_valid[i]  = 1'b1;
                end
                VFWCVTBF16,
                `endif
                VFCVT_XUFV, 
                VFCVT_XFV,
                VFCVT_RTZXUFV,
                VFCVT_RTZXFV,
                VFCVT_FXUV,
                VFCVT_FXV: begin
                  vd_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
                  vd_valid[i]  = 1'b1;
                end
              endcase              
            end

            VWRFUNARY0: begin
              case(inst_funct3)
                OPFVF: begin
                  vd_offset[i] = 'b0;
                  vd_valid[i]  = 1'b1;
                end
              endcase
            end
          endcase
        end
        `endif        
      endcase
    end
  end

  // update vd_index and eew 
  always_comb begin
    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_VD_OFFSET
      vd_index[i] = inst_vd + {2'b0, vd_offset[i]};
    end
  end

  // some uop need vd as the vs3 vector operand
  always_comb begin
    // initial
    vs3_valid = 'b0;

    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_VS3_VALID
      case(1'b1)
        valid_opi: begin
          // OPI*
          case(inst_funct6)
            VMADC,
            VMSBC,
            VMSEQ,
            VMSNE,
            VMSLEU,
            VMSLE,
            VMSLTU,
            VMSLT,
            VMSGTU,
            VMSGT: begin
              vs3_valid[i] = last_uop_valid[i];
            end
          endcase
        end

        valid_opm: begin
          // OPM*
          case(inst_funct6)
            VMAND,
            VMNAND,
            VMANDN,
            VMXOR,
            VMOR,
            VMNOR,
            VMORN,
            VMXNOR : begin
              vs3_valid[i] = (csr_vstart!='b0);
            end
            VMACC,
            VNMSAC,
            VMADD,
            VNMSUB,
            VWMACCU,
            VWMACC,
            VWMACCSU,
            VWMACCUS: begin
              vs3_valid[i] = 1'b1;
            end
            VMUNARY0: begin
              case(inst_funct3)
                OPMVV: begin
                  case(vs1_opcode)
                    VMSBF,
                    VMSIF,
                    VMSOF: begin
                      vs3_valid[i] = (inst_vm==1'b0);
                    end
                  endcase
                end
              endcase
            end
          endcase
        end
        `ifdef ZVE32F_ON
        valid_opf: begin
          // OPF* instruction
          case(inst_funct6)
          `ifdef ZVFBFWMA_ON
            VFWMACCBF16,
          `endif
            VFMACC,
            VFNMACC,
            VFMSAC,
            VFNMSAC,
            VFMADD,
            VFNMADD,
            VFMSUB,
            VFNMSUB: begin
              vs3_valid[i] = 1'b1;
            end
            VMFEQ,
            VMFNE,
            VMFLT,
            VMFLE,
            VMFGT,
            VMFGE: begin
              vs3_valid[i] = last_uop_valid[i];
            end
          endcase
        end
        `endif      
      endcase
    end
  end
  
  // update vs1_offset and valid
  always_comb begin
    vs1_offset = 'b0; 
    vs1_valid  = 'b0;
      
    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_VS1_OFFSET
      case(inst_funct3)
        OPIVV: begin
          case(inst_funct6)
            VADD,
            VSUB,
            VADC,
            VMADC,
            VSBC,
            VMSBC,
            VAND,
            VOR,
            VXOR,
            VSLL,
            VSRL,
            VSRA,
            VMSEQ,
            VMSNE,
            VMSLTU,
            VMSLT,
            VMSLEU,
            VMSLE,
            VMINU,
            VMIN,
            VMAXU,
            VMAX,
            VMERGE_VMV,
            VSADDU,
            VSADD,
            VSSUBU,
            VSSUB,
            VSMUL_VMVNRR,
            VSSRL,
            VSSRA,
            VRGATHER: begin
              vs1_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
              vs1_valid[i]  = 1'b1;   
            end
            
            VNSRL,
            VNSRA,
            VNCLIPU,
            VNCLIP: begin
              vs1_offset[i] = {1'b0, uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:1]};
              vs1_valid[i]  = 1'b1;
            end
            
            VWREDSUMU,
            VWREDSUM: begin
              vs1_offset[i] = 'b0;
              vs1_valid[i]  = first_uop_valid[i];
            end        
            
            VSLIDEUP_RGATHEREI16: begin
              case({emul_max,emul_vs1})
                {EMUL1,EMUL1},
                {EMUL2,EMUL2},
                {EMUL4,EMUL4},
                {EMUL8,EMUL8}: begin
                  vs1_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
                  vs1_valid[i]  = 1'b1;
                end
                {EMUL2,EMUL1},
                {EMUL4,EMUL2},
                {EMUL8,EMUL4}: begin              
                  vs1_offset[i] = {1'b0, uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:1]};
                  vs1_valid[i]  = 1'b1;
                end
              endcase
            end
          endcase
        end

        OPMVV: begin
          case(inst_funct6)
            VWADDU,
            VWSUBU,
            VWADD,
            VWSUB,
            VWADDU_W,
            VWSUBU_W,
            VWADD_W,
            VWSUB_W,
            VWMUL,
            VWMULU,
            VWMULSU,
            VWMACCU,
            VWMACC,
            VWMACCSU: begin
              vs1_offset[i] = {1'b0, uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:1]};
              vs1_valid[i]  = 1'b1;        
            end

            VMUL,
            VMULH,
            VMULHU,
            VMULHSU,
            VDIVU,
            VDIV,
            VREMU,
            VREM,
            VMACC,
            VNMSAC,
            VMADD,
            VNMSUB,
            VAADDU,
            VAADD,
            VASUBU,
            VASUB: begin
              vs1_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
              vs1_valid[i]  = 1'b1;        
            end

            // reduction
            VREDSUM,
            VREDMAXU,
            VREDMAX,
            VREDMINU,
            VREDMIN,
            VREDAND,
            VREDOR,
            VREDXOR: begin
              vs1_offset[i] = 'b0;
              vs1_valid[i]  = first_uop_valid[i];
            end

            VMAND,
            VMNAND,
            VMANDN,
            VMXOR,
            VMOR,
            VMNOR,
            VMORN,
            VMXNOR: begin
              vs1_offset[i] = 'b0;
              vs1_valid[i]  = 1'b1;
            end

            VCOMPRESS: begin
              vs1_offset[i] = 'b0;
              vs1_valid[i]  = first_uop_valid[i];        
            end
          endcase
        end
        
        `ifdef ZVE32F_ON
        OPFVV: begin
          case(inst_funct6)
            `ifdef ZVFBFWMA_ON
            VFWMACCBF16: begin
              vs1_offset[i] = {1'b0, uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:1]};
              vs1_valid[i]  = 1'b1;        
            end

            `endif
            VFADD,          
            VFSUB,      
            VFMUL,      
            VFDIV,      
            VFMACC,     
            VFNMACC,    
            VFMSAC,     
            VFNMSAC,    
            VFMADD,     
            VFNMADD,    
            VFMSUB,     
            VFNMSUB,    
            VFMIN,
            VFMAX,
            VFSGNJ,
            VFSGNJN,
            VFSGNJX,
            VMFEQ,
            VMFNE,
            VMFLT,
            VMFLE,
            VMFGT,
            VMFGE: begin
              vs1_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
              vs1_valid[i]  = 1'b1;        
            end

            VFMERGE_VFMV: begin
              vs1_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
              vs1_valid[i]  = !inst_vm;        
            end

            VFREDOSUM,
            VFREDUSUM,
            VFREDMAX,
            VFREDMIN: begin
              vs1_offset[i] = 'b0;
              vs1_valid[i]  = first_uop_valid[i];
            end
          endcase
        end
        `endif
      endcase
    end
  end

  // update vs1(index or opcode) and eew
  always_comb begin 
    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_VS1
      vs1[i] = inst_vs1 + {2'b0, vs1_offset[i]}; 
    end
  end

  // update vs2 offset and valid  
  always_comb begin
    // initial
    vs2_offset = 'b0; 
    vs2_valid = 'b0; 
      
    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_VS2_OFFSET
      case(1'b1)
        valid_opi: begin
          // OPI*
          case(inst_funct6)
            VADD,
            VSUB,
            VRSUB,
            VADC,
            VSBC,
            VMADC,
            VMSBC,
            VAND,
            VOR,
            VXOR,
            VSLL,
            VSRL,
            VSRA,
            VNSRL,
            VNSRA,
            VMSEQ,
            VMSNE,
            VMSLTU,
            VMSLT,
            VMSLEU,
            VMSLE,
            VMSGTU,
            VMSGT,
            VMINU,
            VMIN,
            VMAXU,
            VMAX,
            VSADDU,
            VSADD,
            VSSUBU,
            VSSUB,
            VSMUL_VMVNRR,
            VSSRL,
            VSSRA,
            VNCLIPU,
            VNCLIP,
            VWREDSUMU,
            VWREDSUM: begin
              vs2_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
              vs2_valid[i]  = 1'b1;
            end

            VMERGE_VMV: begin
              vs2_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
              vs2_valid[i]  = !inst_vm;
            end
          endcase
        end

        valid_opm: begin
          // OPM* 
          case(inst_funct6)
            VWADDU,
            VWSUBU,
            VWADD,
            VWSUB,
            VWMUL,
            VWMULU,
            VWMULSU,
            VWMACCU,
            VWMACC,
            VWMACCSU,
            VWMACCUS: begin
              vs2_offset[i] = {1'b0, uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:1]};
              vs2_valid[i]  = 1'b1;        
            end
            
            VWADDU_W,
            VWSUBU_W,
            VWADD_W,
            VWSUB_W,
            VMUL,
            VMULH,
            VMULHU,
            VMULHSU,
            VDIVU,
            VDIV,
            VREMU,
            VREM,
            VMACC,
            VNMSAC,
            VMADD,
            VNMSUB,
            VAADDU,
            VAADD,
            VASUBU,
            VASUB,
            VREDSUM,
            VREDMAXU,
            VREDMAX,
            VREDMINU,
            VREDMIN,
            VREDAND,
            VREDOR,
            VREDXOR,
            VWRXUNARY0:begin
              vs2_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
              vs2_valid[i]  = 1'b1;        
            end

            VXUNARY0: begin
              case(inst_funct3)
                OPMVV: begin
                  case({emul_max,emul_vs2})
                    {EMUL1,EMUL1},
                    {EMUL2,EMUL1},
                    {EMUL4,EMUL1}: begin
                      vs2_offset[i] = 'b0;
                      vs2_valid[i]  = 1'b1;
                    end
                    {EMUL4,EMUL2},
                    {EMUL8,EMUL4}: begin
                      vs2_offset[i] = {1'b0, uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:1]};
                      vs2_valid[i]  = 1'b1;
                    end
                    {EMUL8,EMUL2}: begin
                      vs2_offset[i] = {2'b0, uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:2]};
                      vs2_valid[i]  = 1'b1;
                    end
                  endcase
                end
              endcase
            end

            VMAND,
            VMNAND,
            VMANDN,
            VMXOR,
            VMOR,
            VMNOR,
            VMORN,
            VMXNOR: begin
              vs2_offset[i] = 'b0;
              vs2_valid[i]  = 1'b1;   
            end

            VMUNARY0: begin
              case(inst_funct3)
                OPMVV: begin
                  case(vs1_opcode)
                    VMSBF,
                    VMSIF,
                    VMSOF,
                    VIOTA: begin
                      vs2_offset[i] = 'b0;
                      vs2_valid[i]  = 1'b1;   
                    end
                  endcase
                end
              endcase
            end
          endcase
        end

        `ifdef ZVE32F_ON
        valid_opf: begin
          case(inst_funct6)
            `ifdef ZVFBFWMA_ON
            VFWMACCBF16: begin
              vs2_offset[i] = {1'b0, uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:1]};
              vs2_valid[i]  = 1'b1;        
            end
            `endif

            VFADD,          
            VFSUB,      
            VFRSUB,     
            VFMUL,      
            VFDIV,      
            VFRDIV,     
            VFMACC,     
            VFNMACC,    
            VFMSAC,     
            VFNMSAC,    
            VFMADD,     
            VFNMADD,    
            VFMSUB,     
            VFNMSUB,    
            VFUNARY1,
            VFMIN,
            VFMAX,
            VFSGNJ,
            VFSGNJN,
            VFSGNJX,
            VMFEQ,
            VMFNE,
            VMFLT,
            VMFLE,
            VMFGT,
            VMFGE,
            VFREDOSUM,
            VFREDUSUM,
            VFREDMAX,
            VFREDMIN: begin
              vs2_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
              vs2_valid[i]  = 1'b1;        
            end

            VFMERGE_VFMV: begin
              if(!inst_vm) begin
                vs2_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
                vs2_valid[i]  = 1'b1; 
              end
            end

            VFUNARY0: begin
              case(vs1_opcode)
                `ifdef ZVFBFWMA_ON
                VFWCVTBF16: begin
                  vs2_offset[i] = {1'b0, uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:1]};
                  vs2_valid[i]  = 1'b1;        
                end

                VFNCVTBF16,
                `endif
                VFCVT_XUFV,
                VFCVT_XFV,  
                VFCVT_RTZXUFV,
                VFCVT_RTZXFV,
                VFCVT_FXUV,
                VFCVT_FXV: begin
                  vs2_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
                  vs2_valid[i]  = 1'b1;        
                end
              endcase
            end

            VWRFUNARY0: begin
              if(inst_vm) begin
                vs2_offset[i] = uop_index_current[i][`UOP_INDEX_WIDTH_ALU-1:0];
                vs2_valid[i]  = 1'b1; 
              end
            end
          endcase
        end
        `endif
      endcase
    end
  end

  // update vs2 index and eew   
  always_comb begin
    for(int i=0;i<`NUM_DE_UOP;i++) begin: GET_VS2
      vs2_index[i] = inst_vs2 + {2'b0, vs2_offset[i]}; 
    end
  end

  // update scalar dst_index and valid
  always_comb begin
    // initial
    xd_valid = 'b0;
  `ifdef ZVE32F_ON
    fd_valid = 'b0;
